def _quote(s: str) -> str:
    return '"' + s.replace("\\", "\\\\").replace('"', '\\"') + '"'


def _strlist(items: Sequence[str]) -> str:
    """M$Information-style: single -> "x"; many -> {"x", "y"}."""
    if len(items) == 1:
        return _quote(items[0])
    return "{" + ", ".join(_quote(x) for x in items) + "}"


